import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const assetUrl = '/prism-mock/home/nodes/floating-accent.png';
  const map = ctx.textureLoader.load(assetUrl);
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  // Atlas region: 0,0,512,320 within atlas index 0 (assume full-image atlas layout unknown size;
  // default to full texture since atlas dimensions aren't provided beyond this region)
  const atlasW = 512;
  const atlasH = 320;
  const rect = { x: 0, y: 0, w: 512, h: 320 };

  const uvOffset = uniform(vec2(rect.x / atlasW, 1 - (rect.y + rect.h) / atlasH));
  const uvScale = uniform(vec2(rect.w / atlasW, rect.h / atlasH));

  const mappedUV = uv().mul(uvScale).add(uvOffset);

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(map, mappedUV);
  material.transparent = true;
  material.depthWrite = false;
  material.toneMapped = false;

  const aspect = rect.w / rect.h;
  const height = 2.0;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-hero-showpiece';

  mesh.position.set(0, -0.35, -0.6);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  const container = new THREE.Object3D();
  container.name = 'home-hero-showpiece-container';
  container.add(mesh);

  container.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  container.userData.handlers = {};

  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    container.onBeforeRender = null;
  };

  return container;
}
